    while True:
        j=text.find('<?',i)
        if j<0: break
        k=text.find('?>',j+2)
        if k<0:
            k=len(text)
        seg=text[j+2:k]
        if seg.startswith('php'):
            seg=seg[3:]
        elif seg.startswith('='):
            seg=seg[1:]
        yield seg
        if k==len(text): break
        i=k+2

def check(path):
