    stack=[]
    for si,seg in enumerate(php_segments(text),1):
        state='code'; quote=''; esc=False; i=0
        while i<len(seg):
            c=seg[i]; nxt=seg[i+1] if i+1<len(seg) else ''
            if state=='line':
                if c=='\n': state='code'
            elif state=='block':
                if c=='*' and nxt=='/': state='code'; i+=1
            elif state=='string':
                if esc: esc=False
                elif c=='\\': esc=True
                elif c==quote: state='code'
            else:
